        return [[grid[j][N-1-i] for j in range(N)] for i in range(N)]
    BL = rot_90_cw(input_grid)
    for i in range(N):
        for j in range(N):
            output[N+i][j] = BL[i][j]

    # BR = 180
    def rot_180(grid):
        return [row[::-1] for row in grid[::-1]]
    BR = rot_180(input_grid)
    for i in range(N):
        for j in range(N):
            output[N+i][N+j] = BR[i][j]

    return output

# Define candidates
def rot_90_ccw(grid):
    return [[grid[N-1-j][i] for j in range(N)] for i in range(N)]

def rot_90_cw(grid):
    return [[grid[j][N-1-i] for j in range(N)] for i in range(N)]

def transpose(grid):
    return [[grid[j][i] for j in range(N)] for i in range(N)]

def horiz_flip(grid):
    return [row[::-1] for row in grid]

def vert_flip(grid):
    return grid[::-1]

# Test all candidates
candidates = [
    ("90 CCW", rot_90_ccw),
    ("90 CW", rot_90_cw),
    ("Transpose", transpose),
    ("Horizontal flip", horiz_flip),
    ("Vertical flip", vert_flip),
    ("180 rotation", lambda g: [row[::-1] for row in g[::-1]])
]

