# Try Boustrophedon (snake-like) ordering
def boustrophedon_order(grid):
    result = []
    for r in range(len(grid)):
        if r % 2 == 0:
            result.append(grid[r])  # left-to-right
        else:
            result.append(grid[r][::-1])  # right-to-left
    # Flatten and reshape
    flat = []
    for row in result:
        flat.extend(row)
    return [flat[i*N:(i+1)*N] for i in range(N)]

